sql:
select *, concat(method, ' ', status) as method_status
from payments
order by status;

select id, discount, case when amount >= 1750 then 'High' when amount >= 420 then 'Medium' else 'Low' end as amount_band
from orders
where amount between 920 and 930;

select id, store_name
from stores
where region not in ('Central', 'East', 'North');

SELECT *, units * revenue AS revenue_per_unit
FROM store_sales
ORDER BY id DESC;

select a.id, a.account_type
from accounts a
where a.opened_date <= '2024-09-01' and exists (select 1 from transactions t where t.account_id = a.id);

select s.id, s.country, s.city
from suppliers s
where exists (select 1 from products p where p.supplier_id = s.id and p.supplier_id in (17, 37));

SELECT id, amount, UPPER(merchant) AS merchant_upper
FROM transactions
WHERE merchant IN ('Grab', 'Starbucks', '7-Eleven') OR is_flagged = FALSE;

SELECT SUM(quantity) AS total_quantity, MIN(last_restock) AS min_last_restock
FROM inventory
ORDER BY min_last_restock;

SELECT id, device
FROM sessions
WHERE device IN ('desktop', 'tablet', 'mobile') AND (customer_id IS NOT NULL OR browser = 'Firefox');

SELECT id, merchant, SUBSTRING(txn_type, 1, 4) AS txn_type_prefix
FROM transactions
WHERE amount >= 2800;

SELECT DISTINCT status, channel
FROM orders
ORDER BY status;

SELECT product_id, SUM(quantity) AS total_quantity, ROUND(SUM(quantity) * 100.0 / SUM(SUM(quantity)) OVER (), 2) AS pct_of_total
FROM inventory
GROUP BY product_id;

select budget_bucket, dept_name, berlin_count
from (
    select case when budget >= 4436000 then 'high' when budget >= 872000 then 'mid' else 'low' end as budget_bucket, dept_name, count(case when location = 'Berlin' then 1 end) as berlin_count
    from departments
    group by case when budget >= 4436000 then 'high' when budget >= 872000 then 'mid' else 'low' end, dept_name
) as s
where berlin_count > 9;

SELECT departments.id, departments.location, departments.dept_name
FROM departments
WHERE NOT EXISTS (SELECT 1 FROM employees WHERE employees.dept_id = departments.id);

select round(avg(amount), 2) as avg_amount
from payments
where paid_at < '2024-05-01';

SELECT id, discount
FROM orders
WHERE discount > (SELECT AVG(discount) FROM orders);

SELECT id, hire_date, ROW_NUMBER() OVER (ORDER BY hire_date, id) AS row_num
FROM employees
ORDER BY id DESC, hire_date;

SELECT * FROM (SELECT country, city, credit_limit FROM customers)
PIVOT (COUNT(credit_limit) FOR city IN ('New York', 'Chiang Mai'))
ORDER BY country;

select o.id, o.store_id, o.shipping_fee
from orders o
where o.customer_id in (select id from customers where upper(trim(name)) = 'ALICE WONG');

SELECT * FROM (SELECT txn_type, merchant, amount FROM transactions)
PIVOT (COUNT(amount) FOR merchant IN ('Lazada', 'Shell', 'Grab', '7-Eleven'))
ORDER BY txn_type;

SELECT s.id, s.city, s.rating
FROM suppliers s
WHERE s.id IN (SELECT supplier_id FROM products WHERE stock_qty <= 359);

SELECT e.id, e.dept_id, e.is_remote
FROM employees e
WHERE LENGTH(e.email) > 10 AND e.dept_id NOT IN (SELECT id FROM departments WHERE dept_name NOT IN ('Finance', 'Sales'));

SELECT event_type, COUNT(*) AS cnt, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count
FROM web_events
GROUP BY event_type;

SELECT country, SUM(rating) AS total_rating, SUM(SUM(rating)) OVER (ORDER BY country) AS cumulative_rating
FROM suppliers
GROUP BY country;

SELECT s.start_date, s.customer_id, c.is_active
FROM subscriptions s
INNER JOIN customers c ON s.customer_id = c.id;

select id, amount, case when status = 'SUCCESS' then 1 else 0 end as is_success
from payments
where amount >= 1320 and status = 'REFUNDED';

SELECT id, store_name
FROM stores
WHERE sqft = 10336;

SELECT s.id, s.device
FROM sessions s
WHERE s.id IN (SELECT session_id FROM web_events);

SELECT COUNT(DISTINCT shipping_fee) AS unique_channels, MAX(order_date) AS latest_order_date, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list
FROM orders
ORDER BY unique_channels DESC;

SELECT order_items.id, order_items.product_id
FROM order_items
WHERE order_items.order_id IN (SELECT id FROM orders WHERE channel NOT IN ('store', 'partner', 'web'));

select distinct category, brand
from products
order by brand, category desc;

select *
from payments
where method = 'promptpay';

SELECT email, job_title
FROM employees
WHERE job_title IS NULL;

select *
from order_items
where not (product_id is not null and (quantity > 4 or product_id = 38));

select *
from web_events
where duration_sec > 165 and session_id in (10, 17, 34, 36);

SELECT stores.id, stores.city
FROM stores
WHERE EXISTS (SELECT 1 FROM inventory WHERE inventory.store_id = stores.id AND inventory.store_id IN (1, 6));

select *, concat_ws('/', method, status) as method_status_key, case when status = 'FAILED' then 1 else 0 end as is_failed
from payments
where amount <= 1500;

SELECT id, start_date, monthly_fee
FROM subscriptions
WHERE customer_id IS NOT NULL AND customer_id IN (23, 38) AND end_date > '2024-07-01';

SELECT id, country
FROM sessions
WHERE browser <> 'Firefox' AND browser IN ('Edge', 'Safari');

SELECT id, location, COALESCE(budget, 0) AS budget_filled
FROM departments
WHERE location = 'Singapore' AND dept_name = 'Legal';

SELECT d.id, d.location
FROM departments d
WHERE d.budget < 1108000 AND EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);

SELECT id, supplier_name, city
FROM suppliers
ORDER BY id DESC;

select id, account_type, opened_date
from (
    select *, row_number() over (partition by account_type order by opened_date, id) as row_num
    from accounts
    where opened_date <= '2023-09-18'
) as ranked
where row_num <= 3
order by account_type desc;

select amount, case when txn_type = 'DEBIT' then 1 else 0 end is_debit
from transactions
where account_id in (4, 8, 34);

SELECT *
FROM customers
WHERE email LIKE '%@gmail.com';

SELECT tags, launch_date, price
FROM products
WHERE brand IN ('Umbrella', 'Acme', 'Initech') AND (launch_date < '2024-03-01' OR brand = 'Acme');

select *
from (
    select quarter(end_date) end_quarter, count(distinct monthly_fee) unique_plans
    from subscriptions
    group by quarter(end_date)
) t
where unique_plans > 7
order by end_quarter desc
limit 10;

SELECT s.device, c.segment, c.email
FROM sessions s
LEFT JOIN customers c ON s.customer_id = c.id;

SELECT * FROM (SELECT status, carrier, cost FROM shipments)
PIVOT (MAX(cost) FOR carrier IN ('Flash', 'FedEx', 'UPS'))
ORDER BY status;

SELECT cost, CASE WHEN cost >= 87 THEN 'High' WHEN cost >= 18 THEN 'Medium' ELSE 'Low' END AS cost_tier
FROM shipments
WHERE delivered_date >= '2023-03-01' AND YEAR(delivered_date) >= 2024;

select id, account_id, amount
from (
    select *, dense_rank() over (partition by account_id order by amount) pos
    from transactions
) r
where pos <= 3;

SELECT id, store_id, COALESCE(quantity, 0) AS quantity_filled
FROM inventory
ORDER BY store_id DESC, quantity_filled DESC;

SELECT * FROM (SELECT city, country, rating FROM suppliers)
PIVOT (MAX(rating) FOR country IN ('JP', 'DE'))
ORDER BY city;

SELECT *, DATE_TRUNC('MONTH', signup_date) AS signup_date_period
FROM customers
WHERE segment IS NOT NULL AND (credit_limit < 6800 OR city IS NOT NULL);

select id, supplier_id, price
from (
    select *, row_number() over (partition by supplier_id order by price desc, id) as row_num
    from products
) as t
where row_num = 1;

SELECT o.id, o.shipping_fee, o.customer_id
FROM orders o
WHERE o.status NOT IN ('PENDING', 'COMPLETED') AND NOT EXISTS (SELECT 1 FROM shipments s WHERE s.order_id = o.id);

SELECT COUNT(price) AS price_count, ROUND((100 * SUM(CASE WHEN brand = 'Umbrella' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_umbrella, COUNT(DISTINCT stock_qty) AS unique_brands
FROM products
ORDER BY pct_umbrella DESC;

SELECT DISTINCT region
FROM stores
WHERE region IN ('East', 'West', 'Central');

SELECT s.id, s.started_at, s.customer_id
FROM sessions s
WHERE s.id IN (SELECT session_id FROM web_events);

SELECT ROUND((100 * SUM(CASE WHEN status = 'REFUNDED' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_refunded, MIN(paid_at) first_paid_at
FROM payments
ORDER BY pct_refunded ASC;

SELECT MONTH(order_date) AS order_month, SUM(amount) AS total_amount, SUM(SUM(amount)) OVER (ORDER BY MONTH(order_date)) AS cumulative_amount
FROM orders
GROUP BY MONTH(order_date);

SELECT *, SUBSTRING(plan, 1, 3) plan_prefix
FROM subscriptions
WHERE MONTH(start_date) IN (5, 7, 10) AND end_date > '2023-06-01';

SELECT *, LENGTH(method) method_length, CONCAT(method, '/', status) method_status
FROM payments
WHERE (amount < 1520 AND method NOT IN ('paypal', 'card')) OR method IS NOT NULL;

SELECT merchant, SUM(amount) AS total_amount, RANK() OVER (ORDER BY SUM(amount) DESC) AS rnk
FROM transactions
GROUP BY merchant;

SELECT id, unit_price, PERCENT_RANK() OVER (ORDER BY unit_price DESC) AS unit_price_pct_rank
FROM order_items
WHERE order_id IN (16, 17);

SELECT s.id, s.monthly_fee
FROM subscriptions s
WHERE MONTH(s.start_date) IN (4, 8, 10) AND s.customer_id NOT IN (SELECT id FROM customers WHERE UPPER(TRIM(email)) = 'IVY@GMAIL.COM');

SELECT s.id, s.store_name
FROM stores s
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.store_id = s.id AND o.customer_id IS NULL);

SELECT id, unit_price
FROM order_items
WHERE unit_price > (SELECT MAX(unit_price) FROM order_items);

select *
from (
    select *, row_number() over (partition by customer_id order by amount desc, id) rnk
    from orders
) ranked
where rnk <= 1
order by rnk desc;

select id, duration_sec, page
from web_events
where duration_sec < (select min(duration_sec) from web_events where duration_sec <> 197);

SELECT status, SUM(amount) AS total_amount, ROUND(SUM(amount) * 100.0 / SUM(SUM(amount)) OVER (), 2) AS pct_of_total
FROM payments
GROUP BY status;

SELECT id, salary
FROM employees
WHERE salary > (SELECT AVG(salary) FROM employees);

select carrier, count(case when status = 'DELIVERED' then 1 end) as delivered_count, max(shipped_date) as latest_shipped_date
from shipments
group by carrier;

select year(signup_date) signup_year, sum(credit_limit) total_credit_limit, round(sum(credit_limit) * 100.0 / sum(sum(credit_limit)) over (), 2) as pct_of_total
from customers
group by year(signup_date);

SELECT ROUND((100 * SUM(CASE WHEN brand = 'Acme' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_acme
FROM products
ORDER BY pct_acme DESC;

SELECT budget, dept_name, LOWER(dept_name) AS dept_name_lower
FROM departments
ORDER BY dept_name_lower;

select s.id, s.customer_id, s.started_at
from sessions s
where s.id in (select session_id from web_events where page = '/checkout');

SELECT id, txn_type
FROM transactions
WHERE account_id IN (13, 19, 20);

SELECT *, ADD_MONTHS(last_restock, 3) AS last_restock_plus_months
FROM inventory
WHERE product_id IN (1, 4, 8, 10) AND product_id IN (3, 4, 5, 9);

SELECT hire_date, manager_id, email
FROM employees
WHERE level IN ('L4', 'L1') AND (job_title IS NULL OR level IN ('L2', 'L4'));

SELECT amount, INITCAP(TRIM(merchant)) AS merchant_title, CAST(is_flagged AS INT) AS is_flagged_flag
FROM transactions
ORDER BY merchant_title;

SELECT started_at, LOWER(browser) AS browser_lower
FROM sessions
WHERE country = 'US';

select c.id, c.city, c.country
from customers c
where exists (select 1 from orders o where o.customer_id = c.id);

select id, store_id, sale_date
from (
    select *, row_number() over (partition by store_id order by sale_date desc, id) as pos
    from store_sales
    where product_id in (2, 3, 4)
) as r
where pos = 1
order by store_id desc;

select signup_quarter, signup_year, unique_segments
from (
    select quarter(signup_date) as signup_quarter, year(signup_date) as signup_year, count(distinct credit_limit) as unique_segments
    from customers
    group by quarter(signup_date), year(signup_date)
) as agg
where unique_segments >= 5;

SELECT id, status, ADD_MONTHS(shipped_date, 1) AS shipped_date_plus_months
FROM shipments
WHERE YEAR(shipped_date) >= 2024 AND order_id IS NOT NULL;

SELECT id, location
FROM departments
WHERE location NOT IN ('Tokyo', 'Chiang Mai') AND dept_name = 'Marketing' AND dept_name IN ('Marketing', 'HR', 'Legal');

SELECT product_id, AVG(quantity) AS avg_quantity
FROM inventory
GROUP BY 1;

SELECT * FROM (SELECT status, carrier, cost FROM shipments)
PIVOT (COUNT(cost) FOR carrier IN ('Kerry', 'UPS'))
ORDER BY status;

SELECT *, INITCAP(TRIM(status)) AS status_title, CONCAT_WS('-', status, method) AS status_method_key
FROM payments
ORDER BY status_method_key DESC;

SELECT category, supplier_id, CONCAT(brand, ' ', category) AS brand_category
FROM products
WHERE price BETWEEN 980 AND 1190;

SELECT i.id, i.product_id, i.store_id
FROM inventory i
WHERE i.store_id IN (SELECT id FROM stores WHERE sqft BETWEEN 10219 AND 13649);

SELECT d.id, d.dept_name, d.location
FROM departments d
WHERE d.id IN (SELECT dept_id FROM employees);

SELECT MAX(last_restock) AS latest_last_restock, SUM(quantity) AS total_quantity, AVG(quantity) AS avg_quantity
FROM inventory
ORDER BY avg_quantity DESC, latest_last_restock;

SELECT s.id, s.delivered_date, s.shipped_date
FROM shipments s
WHERE s.status = 'RETURNED' AND s.order_id IN (SELECT id FROM orders WHERE store_id IS NULL);

SELECT DISTINCT status, account_type
FROM accounts
WHERE balance BETWEEN 16000 AND 22000;

SELECT AVG(duration_sec) AS avg_duration_sec, COUNT(CASE WHEN page = '/cart' THEN 1 END) AS cart_count
FROM web_events
ORDER BY avg_duration_sec DESC;

SELECT order_id, status, TRIM(status) AS clean_status
FROM payments
WHERE method <> 'paypal';

SELECT COUNT(DISTINCT shipping_fee) AS unique_channels, ROUND(AVG(shipping_fee), 2) AS avg_shipping_fee, SUM(amount) AS total_amount
FROM orders
WHERE order_date < '2025-08-25' AND store_id = 1;

select e.id, e.dept_id
from employees e
where e.dept_id in (select id from departments where budget > 3563000);

select id, product_id, last_restock
from inventory
where store_id in (2, 5);

SELECT dept_id, email, CONCAT(full_name, ' - ', email) AS full_name_email
FROM employees
WHERE job_title = 'Manager';

SELECT s.id, s.start_date, s.end_date
FROM subscriptions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE country IN ('DE', 'JP', 'UK'));

select id, product_id, units
from (
    select
        id,
        product_id,
        units,
        row_number() over (partition by product_id order by units desc, id) as rnk
    from store_sales
) as t
where rnk <= 3;

SELECT id, delivered_date, order_id
FROM shipments
WHERE carrier IS NOT NULL;

select city, max(rating) as max_rating, round((100 * sum(case when city = 'Chiang Mai' then 1 else 0 end)) / count(*), 1) as pct_chiang_mai
from suppliers
group by city;

select id, sale_date
from store_sales
where product_id in (3, 4, 5, 9);

SELECT *
FROM shipments
WHERE cost < 80 OR shipped_date BETWEEN '2023-05-01' AND '2024-08-05';

SELECT we.id, we.session_id, we.event_time
FROM web_events we
WHERE we.session_id IN (7, 18, 40) AND we.session_id NOT IN (SELECT id FROM sessions WHERE device = 'mobile');

SELECT id, job_title, salary
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY salary DESC, id) AS pos
    FROM employees
) AS r
WHERE pos <= 3;

SELECT order_date, CAST(amount AS INT) AS amount_int
FROM orders
WHERE status IN ('RETURNED', 'CANCELLED') OR shipping_fee BETWEEN 10 AND 31;

SELECT store_id, AVG(revenue) AS avg_revenue, AVG(units) AS avg_units
FROM store_sales
GROUP BY store_id;

SELECT id, merchant, amount
FROM transactions
WHERE account_id IN (20, 32) OR amount <= 3300;

SELECT s.order_id, o.channel
FROM shipments s
LEFT JOIN orders o ON s.order_id = o.id;

SELECT carrier, SUM(cost) AS total_cost, DENSE_RANK() OVER (ORDER BY SUM(cost) DESC) AS cost_rank
FROM shipments
GROUP BY carrier;

SELECT id, end_date, start_date
FROM subscriptions
WHERE end_date = (SELECT MAX(end_date) FROM subscriptions);

SELECT * FROM (SELECT supplier_id, category, stock_qty FROM products WHERE price <= 990)
PIVOT (COUNT(stock_qty) FOR category IN ('Fashion', 'Electronics', 'Home', 'Grocery'))
ORDER BY supplier_id;

SELECT departments.id, departments.dept_name
FROM departments
WHERE departments.location = 'London' AND NOT EXISTS (SELECT 1 FROM employees WHERE employees.dept_id = departments.id AND employees.job_title IN ('Analyst', 'Manager'));

SELECT * FROM (SELECT plan, status, monthly_fee FROM subscriptions)
PIVOT (AVG(monthly_fee) FOR status IN ('EXPIRED', 'PAUSED'))
ORDER BY plan;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY start_date DESC, id) rnk
    FROM subscriptions
) t
WHERE rnk = 1;

SELECT id, country, DATEDIFF(CURRENT_DATE(), started_at) AS days_since_started_at
FROM sessions
WHERE customer_id = 16 AND (customer_id = 15 OR browser IS NOT NULL);

SELECT id, salary
FROM employees
WHERE salary >= (SELECT MAX(salary) FROM employees);

SELECT product_id
FROM store_sales
WHERE product_id IN (2, 4, 8, 9);

SELECT id, amount
FROM payments
WHERE amount <= (SELECT MIN(amount) FROM payments);

SELECT event_time, page
FROM web_events
WHERE event_type IN ('search', 'click') AND event_type IN ('add_to_cart', 'page_view', 'purchase');

SELECT order_id, status, cost
FROM shipments
WHERE (delivered_date >= '2025-03-01' AND shipped_date > '2023-06-01') OR shipped_date BETWEEN '2023-03-03' AND '2024-01-19';

SELECT AVG(quantity) AS avg_quantity, SUM(unit_price * quantity) AS revenue, AVG(unit_price) AS avg_unit_price
FROM order_items
ORDER BY avg_unit_price DESC, revenue DESC;

select customer_id, started_at, initcap(trim(browser)) as browser_title
from sessions
where started_at >= '2025-01-14';

SELECT *
FROM (
    SELECT *, RANK() OVER (PARTITION BY brand ORDER BY stock_qty DESC) AS rnk
    FROM products
) AS ranked
WHERE rnk <= 2;

SELECT budget, location
FROM departments
WHERE budget >= 2851000 AND location = 'Berlin' AND location IS NOT NULL;

SELECT s.supplier_name, p.price
FROM suppliers s
LEFT OUTER JOIN products p ON s.id = p.supplier_id;

SELECT id, product_id, quantity - unit_price AS line_total
FROM order_items
WHERE product_id IN (5, 20) AND quantity IS NOT NULL;

SELECT *, CASE WHEN age >= 61 THEN 'High' WHEN age >= 26 THEN 'Medium' ELSE 'Low' END AS age_band
FROM customers
ORDER BY credit_limit;

SELECT id, age
FROM customers
WHERE age >= (SELECT MAX(age) FROM customers);

SELECT COUNT(sqft) AS sqft_count
FROM stores
ORDER BY sqft_count DESC;

select id, brand, stock_qty
from (
    select *, row_number() over (partition by brand order by stock_qty, id) as row_num
    from products
) as ranked
where row_num = 1;

select hire_quarter, total_count
from (
    select quarter(hire_date) as hire_quarter, count(*) as total_count
    from employees
    group by quarter(hire_date)
) as t
where total_count < 6;

SELECT * FROM (SELECT channel, status, shipping_fee FROM orders)
PIVOT (COUNT(shipping_fee) FOR status IN ('RETURNED', 'PENDING', 'SHIPPED'))
ORDER BY channel;

SELECT segment, SUM(credit_limit) AS total_credit_limit, DENSE_RANK() OVER (ORDER BY SUM(credit_limit) DESC) AS rnk
FROM customers
GROUP BY segment;

SELECT opened_date, status
FROM accounts
ORDER BY opened_date;

SELECT COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT(DISTINCT budget) AS unique_locations, SUM(CASE WHEN location = 'Bangkok' THEN budget ELSE 0 END) AS bangkok_budget
FROM departments
ORDER BY bangkok_budget DESC, unique_locations DESC;

SELECT id, revenue, sale_date
FROM store_sales
WHERE revenue > (SELECT AVG(revenue) FROM store_sales);

SELECT e.level, d.location, d.budget
FROM employees e
RIGHT JOIN departments d ON e.dept_id = d.id;

select o.id, o.shipping_fee
from orders o
where o.id in (select order_id from payments where to_date(paid_at) >= '2023-05-01');

SELECT t.id, t.merchant, t.is_flagged
FROM transactions t
WHERE t.txn_type IN ('REFUND', 'DEBIT', 'CREDIT') AND t.account_id NOT IN (SELECT id FROM accounts WHERE account_type = 'CHECKING');

SELECT status, amount, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee
FROM orders
ORDER BY amount DESC;

select id, amount, txn_time
from transactions
where amount > (select avg(amount) from transactions);

SELECT ss.id, ss.units
FROM store_sales ss
WHERE ss.product_id IN (SELECT id FROM products WHERE ARRAY_CONTAINS(tags, 'clearance'));

select s.id, s.started_at
from sessions s
where exists (select 1 from web_events we where we.session_id = s.id);

SELECT brand, supplier_id, ROUND(stock_qty, 2) AS stock_qty_rounded
FROM products
WHERE (supplier_id IS NOT NULL AND stock_qty != 200) OR ARRAY_CONTAINS(tags, 'clearance');

SELECT c.id, c.segment
FROM customers c
WHERE c.is_active AND EXISTS (SELECT 1 FROM subscriptions s WHERE s.customer_id = c.id AND YEAR(s.end_date) >= 2025);

SELECT *
FROM transactions
WHERE amount <= 2500 AND (amount > 1200 OR txn_type IN ('FEE', 'CREDIT'));

SELECT order_id, status, LAST_DAY(delivered_date) AS delivered_date_month_end
FROM shipments
WHERE status NOT IN ('RETURNED', 'LOST');

SELECT accounts.id, accounts.balance, accounts.opened_date
FROM accounts
WHERE accounts.id IN (SELECT account_id FROM transactions);

select segment, country, credit_limit_count
from (
    select segment, country, count(credit_limit) as credit_limit_count
    from customers
    where age is not null
    group by segment, country
) as agg
where credit_limit_count < 7
order by country;

SELECT ROUND(STDDEV(units), 2) AS stddev_units, AVG(revenue) AS avg_revenue
FROM store_sales
ORDER BY avg_revenue;

SELECT id, balance, RANK() OVER (ORDER BY balance) AS rnk
FROM accounts
ORDER BY rnk DESC;

SELECT payments.id, payments.method
FROM payments
WHERE payments.order_id NOT IN (SELECT id FROM orders WHERE discount < 0.13);

select *, concat(country, ', ', browser) as country_browser, cast(started_at as date) as started_at_day
from sessions
where started_at >= '2023-12-01' or browser in ('Firefox', 'Safari');

SELECT id, store_id
FROM store_sales
ORDER BY store_id;

SELECT email, QUARTER(hire_date) AS hire_date_quarter, ROUND(salary, 0) AS salary_rounded
FROM employees
WHERE email LIKE '%@startup.io' AND level = 'L5';

select *
from (
    select method, sum(case when method = 'cash' then 1 else 0 end) as cash_count, count(*) as row_count
    from payments
    group by method
) as sub
where row_count < 9;

select id, quantity, unit_price
from order_items
where quantity >= (select avg(quantity) from order_items);

SELECT *, CAST(is_flagged AS INT) AS is_flagged_flag
FROM transactions
WHERE HOUR(txn_time) BETWEEN 10 AND 14;

SELECT quantity, DATE_ADD(last_restock, 84) AS last_restock_plus_84d
FROM inventory
WHERE (quantity BETWEEN 80 AND 228 AND last_restock >= '2024-03-19') OR quantity BETWEEN 113 AND 178;

SELECT d.id, d.budget, d.location
FROM departments d
WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id AND UPPER(TRIM(e.email)) = 'HENRY@STARTUP.IO');

SELECT p.id, p.order_id, p.amount
FROM payments p
WHERE p.method IN ('bank_transfer', 'promptpay', 'card') AND p.order_id IN (SELECT id FROM orders WHERE status = 'COMPLETED');

select *
from (
    select *, row_number() over (partition by region order by opened_date desc, id) as rn
    from stores
    where store_name like '%Mall%'
) as r
where rn <= 2;

SELECT segment, SUM(age) AS total_age, DENSE_RANK() OVER (ORDER BY SUM(age) DESC) AS age_rank
FROM customers
GROUP BY segment;

SELECT id, stock_qty, SUBSTRING(product_name, 1, 4) AS product_name_prefix
FROM products
ORDER BY product_name_prefix DESC;

select id, credit_limit, signup_date
from customers
where credit_limit < (select min(credit_limit) from customers);

SELECT *, DATE_TRUNC('week', sale_date) AS sale_date_period
FROM store_sales
WHERE product_id IN (1, 6) AND product_id = 7;

select *
from (
    select *, row_number() over (partition by country order by rating, id) rn
    from suppliers
) ranked
where rn <= 3
order by country;

SELECT * FROM (SELECT DATE_FORMAT(order_date, 'yyyy-MM') AS order_month, channel, amount FROM orders)
PIVOT (MAX(amount) FOR channel IN ('mobile', 'store', 'partner', 'web'))
ORDER BY order_month;

SELECT id, location, budget
FROM departments
WHERE location NOT IN ('Bangkok', 'Berlin', 'New York') AND budget > 3211000;

SELECT method, AVG(amount) AS avg_amount, MAX(amount) - MIN(amount) AS amount_range
FROM payments
GROUP BY method;

SELECT id, level, is_remote
FROM employees
WHERE level IN ('L4', 'L1', 'L2');

SELECT COUNT(DISTINCT revenue) AS unique_products, ROUND(AVG(units), 2) AS avg_units
FROM store_sales
WHERE revenue < 2800 OR sale_date > '2023-04-02';

SELECT *, LENGTH(city) AS city_length, UPPER(supplier_name) AS supplier_name_upper
FROM suppliers
WHERE supplier_name LIKE '%Global%' AND supplier_name LIKE 'Eu%';

SELECT ss.id, ss.units
FROM store_sales ss
WHERE ss.store_id NOT IN (SELECT id FROM stores WHERE opened_date <= '2023-08-26');

SELECT *, CASE WHEN status IN ('CLOSED', 'OPEN') THEN 'Tier 1' ELSE 'Other' END AS status_group, DATE_FORMAT(opened_date, 'MMM yyyy') AS opened_date_label
FROM accounts
WHERE opened_date >= '2024-03-01' OR account_type IN ('CHECKING', 'CREDIT', 'LOAN');

SELECT ROUND(AVG(quantity), 2) AS avg_quantity
FROM inventory
WHERE store_id = 3 AND quantity <= 135;

SELECT s.id, s.country, s.rating
FROM suppliers s
WHERE s.supplier_name NOT LIKE '%Tra%' AND NOT EXISTS (SELECT 1 FROM products p WHERE p.supplier_id = s.id AND p.cost >= 680);

SELECT MAX(amount) AS max_amount, SUM(CASE WHEN txn_type = 'FEE' THEN amount ELSE 0 END) AS fee_amount
FROM transactions
ORDER BY 1 DESC;

SELECT *
FROM (
    SELECT *, DENSE_RANK() OVER (PARTITION BY txn_type ORDER BY amount DESC) AS rnk
    FROM transactions
) AS r
WHERE rnk <= 5;

select customer_id, num_orders, avg_discount
from (
    select customer_id, count(*) as num_orders, avg(discount) as avg_discount
    from orders
    group by customer_id
) as t
where avg_discount < 0.27;

SELECT id, monthly_fee, ADD_MONTHS(start_date, 6) start_date_plus_months
FROM subscriptions
WHERE status = 'PAUSED' OR customer_id IS NULL;

SELECT *, CONCAT_WS(',', status, account_type) AS status_account_type_key
FROM accounts
WHERE status = 'CLOSED';

SELECT s.id, s.browser, s.started_at
FROM sessions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE name LIKE 'Hen%');

SELECT p.id, p.method
FROM payments p
WHERE p.amount BETWEEN 500 AND 1400 AND p.order_id IN (SELECT id FROM orders WHERE channel IN ('store', 'web'));

select orders.id, orders.discount, orders.shipping_fee
from orders
where orders.customer_id in (select id from customers where age = 38);

select distinct region, city
from stores
order by region;

SELECT id, opened_date
FROM stores
WHERE opened_date = (SELECT MAX(opened_date) FROM stores);

SELECT ss.id, ss.store_id
FROM store_sales ss
WHERE ss.store_id IN (SELECT id FROM stores WHERE city <> 'Berlin');

SELECT t.id, t.txn_type, t.merchant
FROM transactions t
WHERE t.account_id IN (SELECT id FROM accounts WHERE balance >= 22000);

SELECT city, SUM(sqft) total_sqft, DENSE_RANK() OVER (ORDER BY SUM(sqft) DESC) AS rnk
FROM stores
GROUP BY city;

SELECT *
FROM products
WHERE category NOT IN ('Books', 'Sports');

select id, monthly_fee, ntile(2) over (order by monthly_fee, id) as bucket
from subscriptions
where customer_id in (4, 12, 14);

SELECT email
FROM customers
WHERE age IS NOT NULL;

SELECT city, ROUND(AVG(rating), 2) avg_rating
FROM suppliers
GROUP BY city;

SELECT a.id, a.account_type
FROM accounts a
WHERE EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id);

SELECT *
FROM sessions
WHERE browser = 'Safari' OR customer_id IS NOT NULL;

select id, amount, rank() over (order by amount desc) as amount_rank
from transactions
where merchant in ('Amazon', '7-Eleven', 'Shell');

SELECT p.id, p.price
FROM products p
WHERE p.supplier_id = 24 AND NOT EXISTS (SELECT 1 FROM store_sales ss WHERE ss.product_id = p.id);

SELECT s.id, s.started_at
FROM sessions s
WHERE s.country = 'US' AND EXISTS (SELECT 1 FROM web_events we WHERE we.session_id = s.id);

select o.id, o.status, o.shipping_fee
from orders o
where o.order_date < '2024-10-01' and not exists (select 1 from shipments s where s.order_id = o.id);

select id, is_active, least(credit_limit, age) as least_credit_limit_age
from customers
where city in ('Berlin', 'London') and upper(email) like '%VY@%' and city = 'Tokyo';

select s.id, s.rating, s.city
from suppliers s
where not exists (select 1 from products p where p.supplier_id = s.id and p.product_name like '%Sma%');

SELECT supplier_id, brand, ARRAY_JOIN(tags, '|') AS tags_text
FROM products
WHERE product_name IS NOT NULL AND category IN ('Books', 'Grocery');

select id, session_id
from web_events
where not (page = '/cart' and event_type in ('page_view', 'purchase', 'search'));

SELECT QUARTER(shipped_date) AS shipped_quarter, SUM(cost) AS total_cost, ROUND(SUM(cost) * 100.0 / SUM(SUM(cost)) OVER (), 2) AS pct_of_total
FROM shipments
GROUP BY QUARTER(shipped_date);

SELECT i.id, i.product_id, ss.units
FROM inventory i
INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id;

select *
from store_sales
where product_id = 6;

SELECT id, sqft
FROM stores
WHERE sqft > (SELECT AVG(sqft) FROM stores);

select quarter(txn_time) as txn_quarter, concat_ws(', ', sort_array(collect_set(merchant))) as merchant_values, max(amount) as max_amount
from transactions
group by quarter(txn_time);

SELECT id, product_id, units
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY units, id) AS rnk
    FROM store_sales
) AS t
WHERE rnk <= 1;

SELECT a.id, a.status, a.opened_date
FROM accounts a
WHERE NOT EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id);

SELECT product_id, MAX(quantity) - MIN(quantity) quantity_range, SUM(quantity) total_quantity
FROM inventory
