SELECT units
FROM store_sales
WHERE units != 24;

select id, delivered_date
from shipments
where delivered_date = (select min(delivered_date) from shipments);

select id, txn_type, txn_time
from (
    select
        id,
        txn_type,
        txn_time,
        rank() over (partition by txn_type order by txn_time desc) rn
    from transactions
) r
where rn = 1;

SELECT * FROM (SELECT is_flagged, merchant, amount FROM transactions)
PIVOT (SUM(amount) FOR merchant IN ('Starbucks', 'Grab', 'Lazada'))
ORDER BY is_flagged;

SELECT id, country
FROM suppliers
WHERE city = 'Tokyo';

SELECT product_id, COUNT(DISTINCT unit_price) AS unique_products
FROM order_items
