select session_id, case when duration_sec >= 434 then 'high' when duration_sec >= 82 then 'mid' else 'low' end duration_sec_bucket, max(duration_sec) - min(duration_sec) duration_sec_range
from web_events
group by session_id, case when duration_sec >= 434 then 'high' when duration_sec >= 82 then 'mid' else 'low' end;

SELECT started_at, COALESCE(country, 'Unknown') AS country_filled
FROM sessions
ORDER BY started_at;

select o.id, o.store_id
from orders o
where o.channel = 'store' and o.customer_id in (select id from customers where age >= 54);

SELECT * FROM (SELECT is_remote, level, salary FROM employees)
PIVOT (SUM(salary) FOR level IN ('L5', 'L4', 'L1'))
ORDER BY is_remote;

select departments.id, departments.location
from departments
where departments.budget < 2613000 and not exists (select 1 from employees where employees.dept_id = departments.id and employees.is_remote = true);

SELECT id, account_type, CAST(balance AS INT) AS balance_int
FROM accounts
