select p.id, p.category
from products p
where p.supplier_id in (select id from suppliers where city = 'New York');

select sqft, region, dayofweek(opened_date) as opened_date_dayofweek
from stores
where opened_date >= '2024-12-01' and store_name like '%Downtown%';

SELECT e.id, e.level, e.hire_date
FROM employees e
WHERE e.salary BETWEEN 104000 AND 144000 AND e.dept_id NOT IN (SELECT id FROM departments WHERE location = 'Singapore');

select *
from (
    select
        id,
        account_id,
        amount,
        row_number() over (partition by account_id order by amount, id) as pos
    from transactions
) as t
where pos <= 5;

select count(*) as product_count
from products
where category <> 'Fashion';

SELECT id, rating, supplier_name
FROM suppliers
WHERE rating = (SELECT MIN(rating) FROM suppliers);

SELECT *
FROM products
WHERE category = 'Electronics';

select *
from (
    select channel, max(discount) as max_discount
    from orders
    where discount is not null
    group by channel
) as x
where max_discount > 0.34
order by max_discount desc;

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue DESC, id) AS rnk
    FROM store_sales
) AS ranked
WHERE rnk = 1;

select unit_price
from order_items
