SELECT *
FROM suppliers
WHERE supplier_name LIKE '%Parts%';

select *, if(is_flagged, 'Yes', 'No') as is_flagged_label
from transactions
where txn_time < '2025-05-01' and amount < 1100;

select id, session_id, duration_sec
from (
    select *, row_number() over (partition by session_id order by duration_sec desc, id) as rnk
    from web_events
) as r
where rnk = 1;

select unit_price
from order_items
where (unit_price <= 350 and order_id = 21) or quantity between 4 and 8;

SELECT a.customer_id, t.txn_type
FROM accounts a
LEFT JOIN transactions t ON t.account_id = a.id;

SELECT * FROM (SELECT category, brand, cost FROM products)
PIVOT (AVG(cost) FOR brand IN ('Stark', 'Acme', 'Globex', 'Initech'))
ORDER BY category;

select emp.job_title as employee_job_title, emp.salary as employee_salary, mgr.is_remote as manager_is_remote
