SELECT orders.id, orders.discount
FROM orders
WHERE NOT EXISTS (SELECT 1 FROM payments WHERE payments.order_id = orders.id AND payments.paid_at >= '2024-12-01');

SELECT id, country, rating
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating DESC, id) AS pos
    FROM suppliers
) AS ranked
WHERE pos <= 3;

select e.email as employee_email, m.job_title as manager_job_title
from employees e
join employees m on e.manager_id = m.id;

SELECT e.id, e.full_name AS employee_full_name, m.job_title AS manager_job_title
FROM employees e
LEFT JOIN employees m ON e.manager_id = m.id;

SELECT id, hire_date, ROW_NUMBER() OVER (ORDER BY hire_date, id) rn
FROM employees
WHERE salary >= 68000;

SELECT *, CASE WHEN city = 'Berlin' THEN 1 ELSE 0 END AS is_berlin, CONCAT_WS('-', country, supplier_name) AS country_supplier_name_key
FROM suppliers
ORDER BY 7;

SELECT region, city, SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END) singapore_count
FROM stores
GROUP BY 1, 2;

SELECT *, revenue - units AS revenue_per_unit, DATEDIFF(CURRENT_DATE(), sale_date) AS days_since_sale_date
FROM store_sales
WHERE sale_date >= '2025-04-01';

SELECT id, city, UPPER(TRIM(supplier_name)) AS supplier_name_normalized
