WHERE rating >= 3.5 AND country = 'DE' AND rating BETWEEN 2.6 AND 3.5;

SELECT s.id, s.start_date
FROM subscriptions s
WHERE s.customer_id IN (SELECT id FROM customers WHERE country IN ('DE', 'TH'));

SELECT s.sqft, o.store_id, LOWER(s.store_name) store_name_lower
