SELECT MAX(amount) - MIN(amount) AS amount_range
FROM orders
WHERE shipping_fee <= 40;

select region, city, round((100 * sum(case when city = 'Singapore' then 1 else 0 end)) / count(*), 1) as pct_singapore
from stores
group by region, city;

SELECT id, hire_date
FROM employees
WHERE hire_date = (SELECT MIN(hire_date) FROM employees);

select *
from (
    select account_id, sum(case when merchant = 'Grab' then amount else 0 end) as grab_amount
    from transactions
    group by account_id
) as t
where grab_amount > 32
order by account_id desc;

SELECT id, quantity, quantity + unit_price AS line_total
