SELECT p.id, p.status
FROM payments p
WHERE p.status = 'SUCCESS' AND p.order_id IN (SELECT id FROM orders WHERE shipping_fee IS NOT NULL);

SELECT status, DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values
FROM accounts
GROUP BY status, DATE_FORMAT(opened_date, 'yyyy-MM');

select s.id, s.store_name, s.region
from stores s
where s.city = 'London' and exists (select 1 from orders o where o.store_id = s.id and o.amount between 1490 and 1530);

SELECT s.id, s.device
