SELECT s.id, s.order_id, s.shipped_date
FROM shipments s
WHERE s.order_id IN (SELECT id FROM orders WHERE order_date > '2023-03-01');

select round(avg(amount), 2) as avg_amount, max(discount) - min(discount) as discount_range
from orders
order by avg_amount desc, discount_range desc;

SELECT p.id, p.paid_at, p.status
FROM payments p
WHERE p.order_id IN (SELECT id FROM orders WHERE store_id = 24);

SELECT p.id, p.stock_qty, p.cost
