SELECT ROUND(STDDEV(credit_limit), 2) AS stddev_credit_limit
FROM customers
WHERE signup_date BETWEEN '2024-03-01' AND '2024-07-09';

SELECT id, session_id
FROM web_events
WHERE duration_sec > 224;

SELECT id, quantity, order_id
FROM order_items
ORDER BY quantity DESC;

SELECT s.id, s.plan, s.end_date
FROM subscriptions s
WHERE s.customer_id NOT IN (SELECT id FROM customers WHERE credit_limit > 14400);

select a.id, a.status
from accounts a
where a.customer_id in (select id from customers where lower(trim(name)) = 'henry ford');

SELECT YEAR(paid_at) AS paid_year, SUM(amount) AS total_amount, DENSE_RANK() OVER (ORDER BY SUM(amount) DESC) AS rnk
FROM payments
GROUP BY YEAR(paid_at);

SELECT *
FROM web_events
WHERE event_type IN ('page_view', 'add_to_cart') AND (session_id IN (17, 29) OR event_time < '2024-02-08');

SELECT id, amount
FROM orders
WHERE amount <= (SELECT MIN(amount) FROM orders);

SELECT id, shipped_date
FROM shipments
WHERE shipped_date = (SELECT MAX(shipped_date) FROM shipments);

SELECT is_flagged, txn_type, AVG(amount) AS avg_amount
FROM transactions
GROUP BY is_flagged, txn_type;

SELECT COUNT(rating) rating_count
FROM suppliers
WHERE supplier_name LIKE 'To%' AND (supplier_name LIKE 'Tok%' OR LOWER(supplier_name) LIKE '%uro%');

SELECT id, country, INITCAP(TRIM(name)) name_title
