WHERE city = 'Singapore' AND NOT is_active;

SELECT plan, CASE WHEN plan IN ('premium', 'basic') THEN 'Core' ELSE 'Other' END plan_group
FROM subscriptions
WHERE status IN ('CANCELLED', 'ACTIVE') AND start_date <= '2024-12-01' AND customer_id IN (10, 11, 17, 30);

SELECT oi.id, oi.quantity, oi.product_id
FROM order_items oi
WHERE oi.order_id NOT IN (SELECT id FROM orders WHERE discount < 0.38);

select e.id, e.dept_id, d.dept_name
from employees e
right join departments d on d.id = e.dept_id;

SELECT MAX(event_time) AS latest_event_time, SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END) AS add_to_cart_count
FROM web_events
WHERE duration_sec >= 296;

select s.id, s.carrier
from shipments s
where s.order_id not in (select id from orders where store_id in (25, 35, 40));

SELECT CASE WHEN salary >= 126000 THEN 'high' WHEN salary >= 42000 THEN 'mid' ELSE 'low' END salary_bucket, SUM(salary) total_salary, DENSE_RANK() OVER (ORDER BY SUM(salary) DESC) AS rnk
FROM employees
GROUP BY CASE WHEN salary >= 126000 THEN 'high' WHEN salary >= 42000 THEN 'mid' ELSE 'low' END;

SELECT *, DAYOFWEEK(event_time) AS event_time_dayofweek, DAY(event_time) AS event_time_day
FROM web_events
WHERE duration_sec BETWEEN 270 AND 440 AND (TO_DATE(event_time) < '2023-09-22' OR event_type IN ('click', 'purchase'));

select o.id, o.status
from orders o
where o.id in (select order_id from payments where paid_at >= '2024-07-05');

SELECT *, amount * discount AS amount_times_discount
