WHERE channel IS NOT NULL;

SELECT id, product_id, order_id
FROM order_items
ORDER BY order_id DESC;

SELECT * FROM (SELECT is_remote, job_title, salary FROM employees)
PIVOT (AVG(salary) FOR job_title IN ('Designer', 'Engineer', 'Manager'))
ORDER BY is_remote;

select count(distinct salary) as unique_managers
from employees
where job_title in ('Director', 'Engineer', 'Designer');

select id, txn_type, date_format(txn_time, 'yyyy-MM-dd') as txn_time_label
from transactions
where txn_type = 'CREDIT';

SELECT id, started_at, LEAD(started_at, 1) OVER (ORDER BY started_at, id) AS next_started_at
