WHERE c.segment != 'Consumer' AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);

select * from (select location, dept_name, budget from departments where location in ('Berlin', 'Singapore'))
pivot (max(budget) for dept_name in ('Legal', 'Marketing'))
order by location;

select *
from (
    select *, row_number() over (partition by page order by event_time, id) as rn
    from web_events
) as ranked
where rn <= 2;

select * from (select country, city, credit_limit from customers)
pivot (max(credit_limit) for city in ('London', 'Berlin', 'Singapore', 'Tokyo'))
order by country;

select * from (select date_format(hire_date, 'yyyy-MM') as hire_month, job_title, salary from employees)
