order by hire_month;

SELECT sessions.id, sessions.device, sessions.country
FROM sessions
WHERE sessions.device IN ('desktop', 'mobile') AND sessions.customer_id NOT IN (SELECT id FROM customers WHERE signup_date <= '2023-08-17');

SELECT s.id, s.shipped_date, s.carrier
FROM shipments s
WHERE s.order_id IN (SELECT id FROM orders WHERE status = 'CANCELLED');

SELECT orders.id, orders.discount, orders.status
FROM orders
WHERE NOT EXISTS (SELECT 1 FROM payments WHERE payments.order_id = orders.id AND HOUR(payments.paid_at) BETWEEN 12 AND 15);

select i.id, i.last_restock
