SELECT txn_type, merchant, IF(is_flagged, 'Yes', 'No') is_flagged_label
FROM transactions
ORDER BY merchant ASC, is_flagged_label DESC;

select id, order_id, unit_price
from (
    select
        id,
        order_id,
        unit_price,
        row_number() over (partition by order_id order by unit_price desc, id) as row_num
    from order_items
) as ranked
where row_num <= 5;

SELECT session_id, TO_DATE(event_time) AS event_time_date
