select duration_sec
from web_events
where session_id in (5, 11, 14, 21);

select p.id, p.price, p.product_name
from products p
where p.launch_date < '2025-10-01' and p.id in (select product_id from store_sales where product_id in (2, 5, 7, 9));

SELECT *
FROM (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY balance DESC, id) AS pos
    FROM accounts
) AS t
WHERE pos <= 1;

select c.id, c.segment, c.country
from customers c
where c.country in ('SG', 'UK', 'TH') and not exists (select 1 from subscriptions s where s.customer_id = c.id);

SELECT region, store_name
FROM stores
WHERE store_name IS NOT NULL;

select *
from (
    select plan, round(stddev(monthly_fee), 2) stddev_monthly_fee
    from subscriptions
    group by plan
) s
where stddev_monthly_fee > 35
order by stddev_monthly_fee desc, plan
limit 5;

select
    id,
    city,
    rating,
    country
from (
    select *, row_number() over (partition by city order by rating, id) as pos
    from suppliers
) as r
where pos = 1;

select id, category, count(*) over (partition by category) as category_count
from products
where brand <> 'Acme';

select round(stddev(revenue), 2) as stddev_revenue
from store_sales
where not (revenue <= 1500 and (units is null or revenue >= 2100));

select status, stddev_balance
from (
    select status, round(stddev(balance), 2) as stddev_balance
    from accounts
    group by status
) as agg
where stddev_balance < 45
order by stddev_balance desc;

SELECT *
FROM customers
WHERE segment IN ('Corporate', 'Consumer', 'SMB');

SELECT s.id, s.shipped_date
FROM shipments s
WHERE MONTH(s.delivered_date) IN (3, 9, 12) AND s.order_id NOT IN (SELECT id FROM orders WHERE order_date <= '2024-12-03');

SELECT * FROM (SELECT segment, country, age FROM customers)
PIVOT (SUM(age) FOR country IN ('DE', 'JP', 'TH'))
ORDER BY segment;

select id, order_id
