SELECT * FROM (SELECT country, city, credit_limit FROM customers)
PIVOT (AVG(credit_limit) FOR city IN ('Bangkok', 'Chiang Mai'))
ORDER BY country;

SELECT DISTINCT carrier, status
FROM shipments
WHERE status IN ('DELIVERED', 'RETURNED');

SELECT COUNT(monthly_fee) AS monthly_fee_count, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee, MAX(start_date) AS latest_start_date
FROM subscriptions
WHERE monthly_fee <= 170 AND start_date BETWEEN '2023-09-01' AND '2023-09-18';

SELECT t.id, t.is_flagged, t.txn_time
FROM transactions t
WHERE t.account_id IN (SELECT id FROM accounts WHERE balance >= 21000);

SELECT MIN(sale_date) AS min_sale_date, COUNT(DISTINCT units) AS unique_products, MIN(revenue) AS min_revenue
FROM store_sales
WHERE sale_date > '2025-05-01';

select plan, avg_monthly_fee
from (
    select plan, round(avg(monthly_fee), 2) avg_monthly_fee
    from subscriptions
    where year(start_date) = 2025
    group by plan
) x
where avg_monthly_fee >= 62;

SELECT id, cost, supplier_id
FROM products
ORDER BY 3 DESC;

SELECT s.id, s.country
