SELECT * FROM (SELECT plan, status, monthly_fee FROM subscriptions)
PIVOT (COUNT(monthly_fee) FOR status IN ('CANCELLED', 'EXPIRED', 'ACTIVE', 'PAUSED'))
ORDER BY plan;

SELECT sessions.id, sessions.country, sessions.started_at
