SELECT dept_id, ROUND(STDDEV(salary), 2) AS stddev_salary
FROM employees
GROUP BY dept_id;

select page, sum(duration_sec) as total_duration_sec, dense_rank() over (order by sum(duration_sec) desc) as rnk
from web_events
group by page;

SELECT id, shipping_fee
FROM orders
WHERE discount < 0.31;

SELECT id, started_at, RANK() OVER (ORDER BY started_at DESC) AS started_at_rank
FROM sessions
ORDER BY started_at;

select c.id, c.signup_date
from customers c
where not exists (select 1 from orders o where o.customer_id = c.id and o.discount >= 0.11);

SELECT id, discount, customer_id
FROM orders
